148	    private static void OpenFileViewer(LinkMenuContext context)
149	    {
150	        if (string.IsNullOrEmpty(context.Link))
151	            return;
152	
153	        string path = ResolvePath(context, context.Link);
154	        FileLog.Write($"[LinkContextMenuBuilder] OpenFileViewer: {path}");
155	        context.OnViewFile?.Invoke(path);
156	    }
157	
158	    /// <summary>
159	    /// Builds the "Open in Browser" menu item for <paramref name="target"/> (a URL or a local file
160	    /// path). A plain click reopens the remembered default; hovering expands a submenu of "System
161	    /// default" plus each installed browser with its real profiles (re-read from each browser's Local
162	    /// State so newly added profiles appear without a restart).
163	    /// </summary>
164	    private static MenuItem BuildOpenInBrowserMenuItem(ContextMenu menu, LinkMenuContext context, string target)
165	    {
166	        var parent = new MenuItem { Header = "Open in Browser" };
167	
168	        // A submenu parent does NOT raise Click on its header - pressing the header just expands the
169	        // submenu. To make a plain click on the parent reopen the remembered default (while HOVER
170	        // still expands the submenu), intercept the header press in the tunnel phase. The tunnel
171	        // route also passes through this parent for presses on its OWN submenu leaves (descendants),
172	        // so launch the default ONLY when the press lands on the parent's own header rectangle.
173	        parent.AddHandler(InputElement.PointerPressedEvent, (_, e) =>
174	        {
175	            var pos = e.GetPosition(parent);
176	            bool onHeader = pos.X >= 0 && pos.Y >= 0
177	                && pos.X <= parent.Bounds.Width && pos.Y <= parent.Bounds.Height;
178	            if (!onHeader)
179	                return;
180	
181	            e.Handled = true;
182	            menu.Close();
183	            OpenInBrowserDefault(context, target);
184	        }, RoutingStrategies.Tunnel);
185	
186	        var systemItem = new MenuItem { Header = "System default" };
187	        systemItem.Click += (_, e) =>
188	        {
189	            e.Handled = true;
190	            OpenInBrowserSystemDefault(context, target);
191	        };
192	        parent.Items.Add(systemItem);
193	
194	        foreach (var browser in BrowserLauncher.DetectBrowsers())
195	        {
196	            var browserItem = new MenuItem { Header = browser.DisplayName };
197	
198	            var profiles = BrowserLauncher.GetProfiles(browser);
199	            if (profiles.Count == 0)
200	            {
201	                browserItem.Items.Add(new MenuItem { Header = "(no profiles found)", IsEnabled = false });
202	            }
203	            else
204	            {
205	                foreach (var profile in profiles)
206	                {
207	                    string header = profile.Account is null
208	                        ? profile.DisplayName
209	                        : $"{profile.DisplayName} ({profile.Account})";
210	
211	                    var profileItem = new MenuItem { Header = header };
212	                    var capturedBrowser = browser;
213	                    var capturedFolder = profile.FolderName;
214	                    profileItem.Click += (_, e) =>
215	                    {
216	                        e.Handled = true;
217	                        OpenInBrowserProfile(context, target, capturedBrowser, capturedFolder);
218	                    };
219	                    browserItem.Items.Add(profileItem);
220	                }
221	            }
222	
223	            parent.Items.Add(browserItem);
224	        }
225	
226	        return parent;
227	    }
228	
229	    private static void OpenInBrowserDefault(LinkMenuContext context, string target)
230	    {
231	        try
232	        {
233	            var remembered = BrowserDefaultStore.Load();
234	            if (remembered is null)
235	            {
236	                FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault: no remembered default, using system default: {target}");
237	                BrowserLauncher.OpenSystemDefault(target);
238	                return;
239	            }
240	
241	            var browser = BrowserDefaultStore.ResolveBrowser(remembered.ExePath);
242	            BrowserLauncher.OpenWithProfile(target, browser, remembered.ProfileFolder);
243	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault: opened {target} in {browser.DisplayName}/{remembered.ProfileFolder}");
244	        }
245	        catch (Exception ex)
246	        {
247	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault FAILED: {ex.Message}");
248	            context.OnBrowserError?.Invoke($"Could not open in browser.\n\n{ex.Message}");
249	        }
250	    }
251	
252	    private static void OpenInBrowserSystemDefault(LinkMenuContext context, string target)
253	    {
254	        try
255	        {
256	            BrowserLauncher.OpenSystemDefault(target);
257	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserSystemDefault: {target}");
258	        }
259	        catch (Exception ex)
260	        {
261	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserSystemDefault FAILED: {ex.Message}");
262	            context.OnBrowserError?.Invoke($"Could not open in the system default browser.\n\n{ex.Message}");
263	        }
264	    }
265	
266	    private static void OpenInBrowserProfile(LinkMenuContext context, string target, BrowserInfo browser, string profileFolder)
267	    {
268	        try
269	        {
270	            BrowserLauncher.OpenWithProfile(target, browser, profileFolder);
271	            BrowserDefaultStore.Save(new BrowserDefault(browser.ExePath, profileFolder));
272	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserProfile: opened {target} in {browser.DisplayName}/{profileFolder}");
273	        }
274	        catch (Exception ex)
275	        {
276	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserProfile FAILED: {ex.Message}");
277	            context.OnBrowserError?.Invoke($"Could not open in {browser.DisplayName}.\n\n{ex.Message}");
278	        }
279	    }
280	
281	    private static string ResolvePath(LinkMenuContext context, string path)
282	        => LinkDetector.ResolvePath(path, context.RepoPath);
283	}
