1	using System.Text.Json.Nodes;
2	using CcDirector.Core.Configuration;
3	using CcDirector.Core.Utilities;
4	
5	namespace CcDirector.Core.Browsers;
6	
7	/// <summary>
8	/// The remembered "Open in Browser" default: which browser exe and profile folder a plain click
9	/// on the terminal's "Open in Browser" item should reopen. Stored in <c>config.json</c> under
10	/// <c>browser.default</c> so it survives an app restart.
11	/// </summary>
12	public sealed record BrowserDefault(string ExePath, string ProfileFolder);
13	
14	/// <summary>
15	/// Reads and writes the remembered <see cref="BrowserDefault"/> in <c>config.json</c> (via
16	/// <see cref="CcDirectorConfigService"/>, so other config sections are preserved), and resolves a
17	/// stored exe path back to a live <see cref="BrowserInfo"/>.
18	/// </summary>
19	public static class BrowserDefaultStore
20	{
21	    /// <summary>
22	    /// Returns the remembered default, or null if the user has never chosen a browser+profile.
23	    /// A null result legitimately means "use the OS default" - it is not an error.
24	    /// </summary>
25	    public static BrowserDefault? Load()
26	    {
27	        var root = CcDirectorConfigService.ReadRaw();
28	        if (root["browser"]?["default"] is not JsonObject def)
29	            return null;
30	
31	        var exePath = (string?)def["exePath"];
32	        var profileFolder = (string?)def["profileFolder"];
33	        if (string.IsNullOrWhiteSpace(exePath) || string.IsNullOrWhiteSpace(profileFolder))
34	            return null;
35	
36	        return new BrowserDefault(exePath, profileFolder);
37	    }
38	
39	    /// <summary>Persists <paramref name="value"/> as the remembered default in config.json.</summary>
40	    public static void Save(BrowserDefault value)
41	    {
42	        if (value is null) throw new ArgumentNullException(nameof(value));
43	
44	        FileLog.Write($"[BrowserDefaultStore] Save: exe={value.ExePath}, profile={value.ProfileFolder}");
45	        var patch = new JsonObject
46	        {
47	            ["browser"] = new JsonObject
48	            {
49	                ["default"] = new JsonObject
50	                {
51	                    ["exePath"] = value.ExePath,
52	                    ["profileFolder"] = value.ProfileFolder,
53	                }
54	            }
55	        };
56	        CcDirectorConfigService.MergePatch(patch);
57	    }
58	
59	    /// <summary>
60	    /// Returns the remembered default for the repository at <paramref name="repoPath"/>, or null if
61	    /// that repository has never chosen a browser+profile. A null result legitimately means "no
62	    /// repository default" - it is not an error; the caller falls back to the global default.
63	    /// Stored in config.json under <c>browser.repoDefaults.&lt;canonical repo path&gt;</c>, separate
64	    /// from the global <c>browser.default</c>.
65	    /// </summary>
66	    public static BrowserDefault? LoadForRepo(string repoPath)
67	    {
68	        if (string.IsNullOrWhiteSpace(repoPath))
69	            throw new ArgumentException("Repo path is required", nameof(repoPath));
70	
71	        var key = NormalizeRepoKey(repoPath);
72	        FileLog.Write($"[BrowserDefaultStore] LoadForRepo: repo={repoPath}, key={key}");
73	
74	        var root = CcDirectorConfigService.ReadRaw();
75	        if (root["browser"]?["repoDefaults"]?[key] is not JsonObject def)
76	        {
77	            FileLog.Write($"[BrowserDefaultStore] LoadForRepo: no repo default for key={key}");
