        var repoDefaultItem = new MenuItem { Header = "Set as default for this repository" };
        repoDefaultItem.Click += (_, e) =>
        {
            e.Handled = true;
            SetRepoDefaultAndOpen(context, target, capturedBrowser, capturedFolder);
        };
        profileItem.Items.Add(repoDefaultItem);
